import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateChildApplicationHandler } from "../handlers/updateChildApplicationHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";
import type { UpdateApplicationRequest } from "../types/UpdateApplicationRequest";

type Data = Awaited<ReturnType<typeof updateChildApplicationHandler>>;
type Vars = { teamPk: TeamPartition; applicationId: string; body: UpdateApplicationRequest };

export function useUpdateChildApplication(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateChildApplicationHandler(vars.teamPk, vars.applicationId, vars.body),
    ...options,
  });
}
